def die_parse(msg: str, usage: Optional[str] = None, tip: Optional[str] = None) -> None:
    sys.stderr.write(msg)
    if tip:
        sys.stderr.write("\n\n")
        sys.stderr.write(tip)
    if usage:
        sys.stderr.write("\n\n")
        sys.stderr.write(usage)
    sys.stderr.write("\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def parse_args(argv: List[str]) -> Options:
    opts = Options()
    targets: List[str] = []
    i = 0
    after_dd = False
    while i < len(argv):
        arg = argv[i]
        if after_dd:
            targets.append(arg); i += 1; continue
        if arg == "--":
            after_dd = True; i += 1; continue
        if arg.startswith("--") and arg != "--":
            raw = arg[2:]
            if "=" in raw:
                name, val = raw.split("=", 1)
            else:
                name, val = raw, None
            if name not in LONG_NAMES:
                die_parse(
                    f"error: unexpected argument '--{name}' found",
                    usage=f"Usage: {program_name()} [OPTIONS] <TARGET>",
                    tip=f"  tip: to pass '--{name}' as a value, use '-- --{name}'",
                )
            dest = LONG_NAMES[name]
            if name in VALUE_LONGS:
                if val is None:
                    if i + 1 >= len(argv) or argv[i + 1].startswith("-"):
                        disp = LONG_DISPLAY[name]
                        die_parse(f"error: a value is required for '{disp}' but none was supplied")
                    i += 1; val = argv[i]
                set_option_value(opts, dest, val, name)
            else:
                if val is not None:
                    die_parse(f"error: unexpected value '{val}' for '--{name}'")
                setattr(opts, dest, True)
            i += 1; continue
        if arg.startswith("-") and arg != "-":
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch not in SHORT_NAMES:
                    die_parse(
                        f"error: unexpected argument '-{ch}' found",
                        usage=f"Usage: {program_name()} [OPTIONS] <TARGET>",
                        tip=f"  tip: to pass '-{ch}' as a value, use '-- -{ch}'",
                    )
                dest = SHORT_NAMES[ch]
                if ch in VALUE_SHORTS:
                    if j + 1 < len(cluster):
                        val = cluster[j + 1:]
                        j = len(cluster)
                    else:
                        if i + 1 >= len(argv) or argv[i + 1].startswith("-"):
                            lname = next((k for k, v in LONG_NAMES.items() if v == dest and k in LONG_DISPLAY), None)
                            disp = LONG_DISPLAY.get(lname or "", f"-{ch}")
                            die_parse(f"error: a value is required for '{disp}' but none was supplied")
                        i += 1; val = argv[i]
                        j = len(cluster)
                    set_option_value(opts, dest, val, short=ch)
                    break
                else:
                    setattr(opts, dest, True)
                    j += 1
            i += 1; continue
        targets.append(arg)
        i += 1

    if opts.help or opts.version:
        # clap exits before target validation for these two global actions
        return opts
    if not targets:
        # Match common clap usage special-cases for value options when possible.
        usage_opts = ""
        if opts.output is not None:
            usage_opts = "--output <result.html> "
        elif opts.base_url is not None:
            usage_opts = "--base-url <http://localhost/> "
        die_parse(
            "error: the following required arguments were not provided:\n  <TARGET>",
            usage=f"Usage: {program_name()} {usage_opts}<TARGET>",
        )
    if len(targets) > 1:
        extra = targets[1]
        die_parse(
            f"error: unexpected argument '{extra}' found",
            usage=f"Usage: {program_name()} [OPTIONS] <TARGET>",
        )
    opts.target = targets[0]
    if opts.mhtml:
        # MHTML mode in the observed binary disables JavaScript.
        opts.no_js = True
    return opts


def set_option_value(opts: Options, dest: str, val: str, long: Optional[str] = None, short: Optional[str] = None) -> None:
    if dest == "domains":
        opts.domains.append(val)
    elif dest == "timeout":
        try:
            opts.timeout = int(val)
        except ValueError:
            sys.stderr.write(f"error: invalid value '{val}' for '--timeout <60>': invalid digit found in string\n\nFor more information, try '--help'.\n")
            raise SystemExit(2)
    elif dest == "user_agent":
        opts.user_agent = val
    else:
        setattr(opts, dest, val)


# --- DOM -----------------------------------------------------------------

class Node:
    __slots__ = ("kind", "name", "attrs", "children", "data", "parent", "inserted_close")
    def __init__(self, kind: str, name: str = "", attrs: Optional[List[Tuple[str, Optional[str]]]] = None,
                 data: str = "", inserted_close: bool = False):
        self.kind = kind
        self.name = name
        self.attrs = attrs or []
        self.children: List[Node] = []
        self.data = data
        self.parent: Optional[Node] = None
        self.inserted_close = inserted_close

    def append(self, child: "Node") -> "Node":
        child.parent = self
        self.children.append(child)
        return child

    def insert(self, idx: int, child: "Node") -> "Node":
        child.parent = self
        self.children.insert(idx, child)
        return child

    def remove(self, child: "Node") -> None:
        self.children.remove(child)
        child.parent = None


def elem(name: str, attrs: Optional[List[Tuple[str, Optional[str]]]] = None, inserted_close: bool = False) -> Node:
    return Node("element", name.lower(), attrs or [], inserted_close=inserted_close)


def text(data: str) -> Node:
    return Node("text", data=data)


def comment(data: str) -> Node:
    return Node("comment", data=data)


def doctype(data: str) -> Node:
    return Node("doctype", data=data)


def attr_index(n: Node, key: str) -> int:
    kl = key.lower()
    for i, (k, _v) in enumerate(n.attrs):
        if k.lower() == kl:
            return i
    return -1


def get_attr(n: Node, key: str) -> Optional[str]:
    i = attr_index(n, key)
    if i >= 0:
        v = n.attrs[i][1]
        return "" if v is None else v
    return None


def has_attr(n: Node, key: str) -> bool:
    return attr_index(n, key) >= 0


def set_attr(n: Node, key: str, value: str) -> None:
    i = attr_index(n, key)
    if i >= 0:
        oldk, _ = n.attrs[i]
        n.attrs[i] = (oldk, value)
    else:
        n.attrs.append((key.lower(), value))


def del_attr(n: Node, key: str) -> None:
    i = attr_index(n, key)
    if i >= 0:
        del n.attrs[i]


def rel_tokens(n: Node) -> List[str]:
    r = get_attr(n, "rel") or ""
    return [x.lower() for x in re.split(r"\s+", r.strip()) if x]


class Parser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = Node("root")
        self.stack: List[Node] = [self.root]

    def cur(self) -> Node:
        return self.stack[-1]

    def in_raw(self) -> bool:
        return any(n.kind == "element" and n.name in ("script", "style") for n in self.stack[1:])

    def handle_decl(self, decl: str) -> None:
        if decl.lower().startswith("doctype"):
            self.cur().append(doctype(decl[7:].strip()))
        else:
            self.cur().append(comment("!" + decl))

    def handle_pi(self, data: str) -> None:
        self.cur().append(text("<?" + data + ">"))

    def handle_comment(self, data: str) -> None:
        self.cur().append(comment(data))

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        n = elem(tag, [(k.lower(), v) for k, v in attrs])
        self.cur().append(n)
        if tag.lower() not in VOID_TAGS:
            self.stack.append(n)

    def handle_startendtag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        n = elem(tag, [(k.lower(), v) for k, v in attrs])
        self.cur().append(n)

    def handle_endtag(self, tag: str) -> None:
        tl = tag.lower()
        for idx in range(len(self.stack) - 1, 0, -1):
            if self.stack[idx].name == tl:
                del self.stack[idx:]
                break

    def handle_data(self, data: str) -> None:
        if data:
            self.cur().append(text(data))

    def handle_entityref(self, name: str) -> None:
        if self.in_raw():
            self.cur().append(text("&" + name + ";"))
            return
        # Decode named entities as an HTML parser would, then serializer escapes
        # the characters that need escaping.  html5 has keys with trailing ';'.
        val = html.entities.html5.get(name + ";") or html.entities.html5.get(name)
        if isinstance(val, tuple):
            val = "".join(chr(x) for x in val)
        self.cur().append(text(val if val is not None else "&" + name + ";"))

    def handle_charref(self, name: str) -> None:
        if self.in_raw():
            self.cur().append(text("&#" + name + ";"))
            return
        try:
            if name.lower().startswith("x"):
                ch = chr(int(name[1:], 16))
            else:
                ch = chr(int(name, 10))
        except Exception:
            ch = "&#" + name + ";"
        self.cur().append(text(ch))


def parse_html(s: str) -> Node:
    p = Parser()
    try:
        p.feed(s)
        p.close()
    except Exception:
        # HTMLParser is forgiving, but in the unlikely event it raises, keep what
        # has been parsed so far.
        pass
    ensure_structure(p.root)
    return p.root


def find_child(parent: Node, name: str) -> Optional[Node]:
    for c in parent.children:
        if c.kind == "element" and c.name == name:
            return c
    return None


def first_element(root: Node, name: str) -> Optional[Node]:
    for n in walk(root):
        if n.kind == "element" and n.name == name:
            return n
    return None


def ensure_structure(root: Node) -> None:
    html_node = None
    for c in root.children:
        if c.kind == "element" and c.name == "html":
            html_node = c
            break
    if html_node is None:
        html_node = elem("html")
        old = root.children[:]
        root.children = []
        for c in old:
            if c.kind in ("doctype", "comment"):
                root.append(c)
            else:
                html_node.append(c)
        root.append(html_node)

    # Move whitespace text after the html element into body, matching html5ever's
    # treatment of trailing whitespace.
    try:
        html_pos = root.children.index(html_node)
        trailing = root.children[html_pos + 1:]
        keep = root.children[:html_pos + 1]
        move_ws: List[Node] = []
        for c in trailing:
            if c.kind == "text" and c.data.strip() == "":
                move_ws.append(c)
            else:
                keep.append(c)
        root.children = keep
        body_for_ws = find_child(html_node, "body")
        if body_for_ws is None:
            body_for_ws = elem("body")
            html_node.append(body_for_ws)
        for c in move_ws:
            body_for_ws.append(c)
    except ValueError:
        pass

    head = find_child(html_node, "head")
    body = find_child(html_node, "body")

    if head is None:
        head = elem("head")
        # Insert before body if present, otherwise after leading comments.
        if body is not None and body in html_node.children:
            html_node.insert(html_node.children.index(body), head)
        else:
            idx = 0
            while idx < len(html_node.children) and html_node.children[idx].kind == "comment":
                idx += 1
            html_node.insert(idx, head)
    if body is None:
        body = elem("body")
        html_node.append(body)

    # Move head-like direct children into head and ordinary content into body.
    for c in html_node.children[:]:
        if c is head or c is body or c.kind == "comment":
            continue
        if c.kind == "element" and c.name in HEAD_TAGS:
            html_node.remove(c); head.append(c)
        elif c.kind == "text" and c.data.strip() == "":
            html_node.remove(c); body.append(c)
        else:
            html_node.remove(c); body.append(c)

    # Keep head before body for newly synthesized documents.
    if head in html_node.children and body in html_node.children:
        hi, bi = html_node.children.index(head), html_node.children.index(body)
        if hi > bi:
            html_node.children.pop(hi)
            html_node.children.insert(bi, head)


def walk(n: Node) -> Iterable[Node]:
    yield n
    for c in list(n.children):
        yield from walk(c)


def element_children(n: Node) -> Iterable[Node]:
    for c in n.children:
        if c.kind == "element":
            yield c


# --- Serialization --------------------------------------------------------

def escape_text(s: str) -> str:
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace("\u00a0", "&nbsp;"))


def escape_attr(s: str) -> str:
    return (s.replace("&", "&amp;")
             .replace('"', "&quot;")
             .replace("\u00a0", "&nbsp;"))


def serialize(n: Node, raw: bool = False) -> str:
    if n.kind == "root":
        return "".join(serialize(c, False) for c in n.children)
    if n.kind == "text":
        return n.data if raw else escape_text(n.data)
    if n.kind == "comment":
        return "<!--" + n.data + "-->"
    if n.kind == "doctype":
        data = n.data.strip()
        if data.lower() == "html":
            return "<!DOCTYPE html>"
        if data.lower().startswith("html"):
            return "<!DOCTYPE " + data + ">"
        return "<!DOCTYPE " + (data or "html") + ">"
    if n.kind == "element":
        attrs = "".join(f' {k}="{escape_attr("" if v is None else str(v))}"' for k, v in n.attrs)
        start = f"<{n.name}{attrs}>"
        is_void = n.name in VOID_TAGS and not n.inserted_close
        if is_void and not n.children:
            return start
        child_raw = n.name in ("script", "style")
        return start + "".join(serialize(c, child_raw) for c in n.children) + f"</{n.name}>"
    return ""


def serialize_document(root: Node, final_newline: bool = True) -> str:
    s = serialize(root)
    if final_newline and not s.endswith("\n"):
        s += "\n"
    return s


# --- Input, URLs, fetching ------------------------------------------------

@dataclass
class FetchResult:
    ok: bool
    data: bytes = b""
    mime: str = "text/plain"
    url: str = ""
    status_msg: Optional[str] = None
    kind: str = ""  # blocked, file_missing, network, builder, http_error, unsupported


def file_url_for_path(path: str) -> str:
    return Path(path).resolve().as_uri()


def path_from_file_url(url: str) -> str:
    p = urllib.parse.urlparse(url)
    return urllib.request.url2pathname(urllib.parse.unquote(p.path))


def normalize_target(target: str) -> Tuple[Optional[str], Optional[str]]:
    """Return (url, immediate_error)."""
    if target == "-":
        return None, None
    parsed = urllib.parse.urlparse(target)
    if parsed.scheme:
        if parsed.scheme in ("http", "https", "file"):
            return target, None
        return None, f'Error: unsupported target URL scheme "{parsed.scheme}"'
    if os.path.exists(target):
        if not os.path.isfile(target):
            return None, f'Error: local target "{target}" is not a file'
        return file_url_for_path(target), None
    # URL-like fallback: the reference prepends http:// to bare host/path input.
    url = "http://" + target
    if "/" not in target and "?" not in target and "#" not in target:
        url += "/"
    return url, None


def sniff_encoding(data: bytes, content_type: str = "", override: Optional[str] = None) -> str:
    if override:
        return override
    if data.startswith(codecs.BOM_UTF8):
        return "utf-8-sig"
    if data.startswith(codecs.BOM_UTF16_LE) or data.startswith(codecs.BOM_UTF16_BE):
        return "utf-16"
    m = re.search(r"charset=([\w.\-]+)", content_type or "", re.I)
    if m:
        return m.group(1)
    # Look for meta charset in the first few KB using an ASCII-compatible pass.
    head = data[:4096].decode("ascii", "ignore")
    m = re.search(r"<meta[^>]+charset\s*=\s*['\"]?\s*([^\s'\"/>;]+)", head, re.I)
    if m:
        return m.group(1)
    m = re.search(r"charset\s*=\s*([^\s'\"/>;]+)", head, re.I)
    if m:
        return m.group(1)
    return "utf-8"


def decode_bytes(data: bytes, content_type: str = "", override: Optional[str] = None) -> str:
    enc = sniff_encoding(data, content_type, override)
    try:
        return data.decode(enc, "replace")
    except LookupError:
        raise
    except Exception:
        return data.decode("utf-8", "replace")


def mime_from_url(url: str, content_type: str = "") -> str:
    if content_type:
        return content_type.split(";", 1)[0].strip().lower() or "text/plain"
    if url.startswith("data:"):
        mt = url[5:].split(",", 1)[0].split(";", 1)[0]
        return mt or "text/plain"
    path = urllib.parse.urlparse(url).path
    mt, _ = mimetypes.guess_type(path)
    return mt or "text/plain"


def make_data_url(data: bytes, mime: str) -> str:
    return f"data:{mime or 'text/plain'};base64," + base64.b64encode(data).decode("ascii")


def decode_data_url(url: str) -> FetchResult:
    try:
        header, payload = url[5:].split(",", 1)
    except ValueError:
        return FetchResult(False, url=url, kind="builder", status_msg=f"builder error for url ({url})")
    mime = header.split(";", 1)[0] or "text/plain"
    if ";base64" in header.lower():
        try:
            data = base64.b64decode(payload, validate=False)
        except Exception:
            data = b""
    else:
        data = urllib.parse.unquote_to_bytes(payload)
    return FetchResult(True, data=data, mime=mime, url=url)


def log(opts: Options, line: str) -> None:
    if not opts.quiet:
        sys.stderr.write(line + "\n")


def domain_matches(host: str, domain: str) -> bool:
    host = (host or "").lower().rstrip(".")
    d = domain.lower().rstrip(".")
    if not d:
        return False
    if d.startswith("."):
        return host.endswith(d) or host == d[1:]
    return host == d


def allowed_by_domains(url: str, opts: Options) -> bool:
    if not opts.domains:
        return True
    p = urllib.parse.urlparse(url)
    host = p.hostname or ""
    matched = any(domain_matches(host, d) for d in opts.domains)
    return (not matched) if opts.blacklist else matched


def load_cookies(opts: Options) -> Optional[str]:
    if not opts.cookie_file:
        return None
    try:
        lines = Path(opts.cookie_file).read_text(errors="replace").splitlines()
    except Exception:
        return f'could not read specified cookie file "{opts.cookie_file}"'
    cookies = []
    for line in lines:
        if not line or line.startswith("#"):
            continue
        parts = line.split("\t")
        if len(parts) < 7:
            parts = re.split(r"\s+", line)
        if len(parts) >= 7:
            dom, flag, path, secure, _exp, name, val = parts[:7]
            cookies.append((dom, flag.upper() == "TRUE", path or "/", secure.upper() == "TRUE", name, val))
    opts.cookies = cookies
    return None


def cookie_header_for(url: str, opts: Options) -> Optional[str]:
    if not opts.cookies:
        return None
    p = urllib.parse.urlparse(url)
    host = p.hostname or ""
    path = p.path or "/"
    is_https = p.scheme == "https"
    pairs = []
    for dom, tailmatch, cpath, secure, name, val in opts.cookies:
        if secure and not is_https:
            continue
        d = dom.lstrip(".")
        if tailmatch:
            ok = host == d or host.endswith("." + d)
        else:
            ok = host == dom
        if ok and path.startswith(cpath):
            pairs.append(f"{name}={val}")
    return "; ".join(pairs) if pairs else None


def fetch(url: str, opts: Options, referer: Optional[str] = None, is_target: bool = False,
          log_success: bool = True, allow_stdin_file: bool = False) -> FetchResult:
    if not url:
        return FetchResult(False, url=url, kind="builder", status_msg=f"builder error for url ({url})")
    parsed = urllib.parse.urlparse(url)
    scheme = parsed.scheme.lower()

    if scheme == "data":
        return decode_data_url(url)
    if scheme in ("javascript", "mailto", "tel", "about", "blob"):
        msg = f"builder error for url ({url})"
        log(opts, f"{url} ({msg})") if scheme == "javascript" and not is_target else None
        return FetchResult(False, url=url, kind="builder", status_msg=msg)

    if scheme in ("http", "https"):
        if not allowed_by_domains(url, opts):
            return FetchResult(False, url=url, kind="blocked")
        headers = {
            "accept": "*/*",
            "user-agent": opts.user_agent,
            "accept-encoding": "gzip, br, deflate",
        }
        if referer:
            headers["referer"] = referer
        ck = cookie_header_for(url, opts)
        if ck:
            headers["cookie"] = ck
        req = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(req, timeout=max(1, opts.timeout)) as r:
                data = r.read()
                enc = (r.headers.get("Content-Encoding") or "").lower()
                try:
                    if enc == "gzip":
                        data = gzip.decompress(data)
                    elif enc == "deflate":
                        data = zlib.decompress(data)
                except Exception:
                    pass
                mime = mime_from_url(url, r.headers.get("Content-Type", ""))
                if log_success:
                    log(opts, url)
                return FetchResult(True, data=data, mime=mime, url=url)
        except urllib.error.HTTPError as e:
            body = e.read() if opts.ignore_errors else b""
            mime = mime_from_url(url, e.headers.get("Content-Type", "") if e.headers else "")
            status = f"{e.code} {e.reason}"
            if opts.ignore_errors:
                if log_success:
                    log(opts, url)
                return FetchResult(True, data=body, mime=mime, url=url)
            if log_success:
                log(opts, f"{url} ({status})")
            return FetchResult(False, url=url, mime=mime, kind="http_error", status_msg=status)
        except Exception:
            msg = f"error sending request for url ({url})"
            if log_success:
                log(opts, f"{url} ({msg})")
            return FetchResult(False, url=url, kind="network", status_msg=msg)

    if scheme == "file":
        # The reference does not retrieve file: assets for a stdin document with a
        # custom file base; model that by allow_stdin_file.
        if opts.stdin_target and not allow_stdin_file and not is_target:
            return FetchResult(False, url=url, kind="unsupported")
        path = path_from_file_url(url)
        if not os.path.exists(path) or not os.path.isfile(path):
            if log_success:
                log(opts, f"{url} (file not found)")
            return FetchResult(False, url=url, kind="file_missing", status_msg="file not found")
        try:
            data = Path(path).read_bytes()
            if log_success:
                log(opts, url)
            return FetchResult(True, data=data, mime=mime_from_url(url), url=url)
        except Exception:
            if log_success:
                log(opts, f"{url} (file not found)")
            return FetchResult(False, url=url, kind="file_missing", status_msg="file not found")

    return FetchResult(False, url=url, kind="unsupported", status_msg=f"builder error for url ({url})")


def resolve_url(value: str, base: Optional[str]) -> Optional[str]:
    if value is None:
        return None
    v = value.strip()
    if not v:
        return v
    p = urllib.parse.urlparse(v)
    if p.scheme:
        return v
    if v.startswith("#"):
        return v
    if base:
        return urllib.parse.urljoin(base, v)
    return None


def absolutize_or_data(value: str, base: Optional[str]) -> str:
    if not value:
        return value
    p = urllib.parse.urlparse(value)
    if p.scheme in ("mailto", "javascript", "tel", "data") or value.startswith("#"):
        return value
    r = resolve_url(value, base)
    return r if r else "data:,"


def empty_asset_data() -> str:
    return "data:text/plain;base64,"


def set_asset_attr(n: Node, attr: str, value: str, base: Optional[str], opts: Options,
                   referer: Optional[str], kind: str = "generic") -> None:
    if not has_attr(n, attr):
        return
    old = get_attr(n, attr) or ""
    resolved = resolve_url(old, base)
    if resolved is None:
        if kind == "script":
            del_attr(n, attr)
        elif kind == "iframe":
            set_attr(n, attr, make_data_url(b"<html><head></head><body></body></html>", "text/plain"))
        else:
            set_attr(n, attr, empty_asset_data())
        return
    fr = fetch(resolved, opts, referer=referer, is_target=False, allow_stdin_file=(not opts.stdin_target))
    if fr.ok:
        set_attr(n, attr, make_data_url(fr.data, fr.mime))
    else:
        if fr.kind == "blocked" or fr.kind in ("network", "http_error"):
            set_attr(n, attr, resolved)
        elif fr.kind == "file_missing" or fr.kind in ("builder", "unsupported"):
            del_attr(n, attr)
        else:
            set_attr(n, attr, resolved)


def fetch_text_asset(url: str, base: Optional[str], opts: Options, referer: Optional[str], default_empty: bool = True) -> Tuple[bool, str, str, str]:
    resolved = resolve_url(url, base)
    if resolved is None:
        return True, "", "text/plain", ""
    fr = fetch(resolved, opts, referer=referer, allow_stdin_file=(not opts.stdin_target))
    if fr.ok:
        try:
            return True, decode_bytes(fr.data, fr.mime), fr.mime, resolved
        except LookupError:
            return True, fr.data.decode("utf-8", "replace"), fr.mime, resolved
    if fr.kind == "blocked" or fr.kind in ("network", "http_error"):
        return False, resolved, fr.mime, resolved
    return (True, "", "text/plain", resolved) if default_empty else (False, resolved, fr.mime, resolved)


# --- CSS and transformations ---------------------------------------------

def remove_font_faces(css: str) -> str:
    # Small balanced-ish remover for @font-face blocks.
    out = []
    i = 0
    low = css.lower()
    while True:
        j = low.find("@font-face", i)
        if j < 0:
            out.append(css[i:]); break
        out.append(css[i:j])
        brace = css.find("{", j)
        if brace < 0:
            i = j + len("@font-face"); continue
        depth = 1; k = brace + 1
        while k < len(css) and depth:
            if css[k] == "{": depth += 1
            elif css[k] == "}": depth -= 1
            k += 1
        i = k
    return "".join(out)


def is_probably_image_url(u: str) -> bool:
    path = urllib.parse.urlparse(u).path.lower()
    return bool(re.search(r"\.(png|jpe?g|gif|webp|svg|bmp|ico|avif)(?:$|[?#])", path)) or not re.search(r"\.(woff2?|ttf|otf|eot)(?:$|[?#])", path)


def process_css(css: str, base: Optional[str], opts: Options, referer: Optional[str]) -> str:
    if opts.no_css:
        return ""
    if opts.no_fonts:
        css = remove_font_faces(css)

    def repl(m: re.Match) -> str:
        raw = m.group(1).strip()
        if (raw.startswith('"') and raw.endswith('"')) or (raw.startswith("'") and raw.endswith("'")):
            raw = raw[1:-1]
        if not raw or raw.startswith("#"):
            return f'url("{raw}")'
        p = urllib.parse.urlparse(raw)
        if p.scheme == "data":
            fr = decode_data_url(raw)
            return f'url("{make_data_url(fr.data, fr.mime) if fr.ok else raw}")'
        if p.scheme in ("javascript", "mailto"):
            return f'url("{raw}")'
        if opts.no_images and is_probably_image_url(raw):
            return f'url("{PLACEHOLDER_PNG}")'
        resolved = resolve_url(raw, base)
        if resolved is None:
            return 'url("data:text/plain;base64,")'
        fr = fetch(resolved, opts, referer=referer, allow_stdin_file=(not opts.stdin_target))
        if fr.ok:
            return f'url("{make_data_url(fr.data, fr.mime)}")'
        if fr.kind in ("blocked", "network", "http_error"):
            return f'url("{resolved}")'
        return 'url("data:text/plain;base64,")'

    return re.sub(r"url\((.*?)\)", repl, css, flags=re.I | re.S)


def process_srcset(value: str, base: Optional[str], opts: Options, referer: Optional[str], no_images: bool) -> str:
    parts = []
    for item in value.split(','):
        item_strip = item.strip()
        if not item_strip:
            continue
        bits = item_strip.split()
        url = bits[0]
        desc = " ".join(bits[1:])
        if no_images:
            newurl = PLACEHOLDER_PNG
        else:
            resolved = resolve_url(url, base)
            if resolved is None:
                newurl = empty_asset_data()
            else:
                fr = fetch(resolved, opts, referer=referer, allow_stdin_file=(not opts.stdin_target))
                if fr.ok:
                    newurl = make_data_url(fr.data, fr.mime)
                elif fr.kind in ("blocked", "network", "http_error"):
                    newurl = resolved
                else:
                    newurl = ""
        parts.append((newurl + ((" " + desc) if desc else "")).strip())
    return ", ".join(parts)


def find_head(root: Node) -> Node:
    h = first_element(root, "head")
    if h is None:
        ensure_structure(root); h = first_element(root, "head")
    return h  # type: ignore


def find_body(root: Node) -> Optional[Node]:
    return first_element(root, "body")


def first_base_href(root: Node) -> Optional[str]:
    h = first_element(root, "head")
    if not h:
        return None
    for n in walk(h):
        if n.kind == "element" and n.name == "base" and has_attr(n, "href"):
            return get_attr(n, "href")
    return None


def insert_or_update_base(root: Node, base_url: str) -> None:
    h = find_head(root)
    for n in walk(h):
        if n.kind == "element" and n.name == "base":
            set_attr(n, "href", base_url)
            return
    h.append(elem("base", [("href", base_url)], inserted_close=True))


def ensure_csp(root: Node, opts: Options) -> None:
    directives: List[str] = []
    if opts.isolate:
        directives.append("default-src 'unsafe-eval' 'unsafe-inline' data:;")
    if opts.no_css:
        directives.append("style-src 'none';")
    if opts.no_fonts:
        directives.append("font-src 'none';")
    if opts.no_frames:
        directives.append("frame-src 'none';")
        directives.append("child-src 'none';")
    if opts.no_js:
        directives.append("script-src 'none';")
    if opts.no_images:
        directives.append("img-src data:;")
    if not directives:
        return
    h = find_head(root)
    csp = elem("meta", [("http-equiv", "Content-Security-Policy"), ("content", " ".join(directives))], inserted_close=True)
    h.insert(0, csp)


def ensure_robots(root: Node) -> None:
    h = find_head(root)
    for n in walk(h):
        if n.kind == "element" and n.name == "meta":
            nm = get_attr(n, "name")
            if nm is not None and nm.lower() == "robots":
                set_attr(n, "content", "none")
                return
    h.append(elem("meta", [("name", "robots"), ("content", "none")], inserted_close=True))


def ensure_encoding_meta(root: Node, enc: Optional[str]) -> None:
    if not enc:
        return
    h = find_head(root)
    for n in walk(h):
        if n.kind == "element" and n.name == "meta" and has_attr(n, "charset"):
            set_attr(n, "charset", enc)
            return
    h.append(elem("meta", [("charset", enc)], inserted_close=True))


def has_icon_link(root: Node) -> bool:
    h = first_element(root, "head")
    if not h:
        return False
    for n in walk(h):
        if n.kind == "element" and n.name == "link" and "icon" in rel_tokens(n):
            return True
    return False


def insert_favicon_if_any(root: Node, target_url: Optional[str], opts: Options) -> None:
    if not target_url or opts.no_images or has_icon_link(root):
        return
    p = urllib.parse.urlparse(target_url)
    if p.scheme not in ("http", "https"):
        return
    fav = urllib.parse.urlunparse((p.scheme, p.netloc, "/favicon.ico", "", "", ""))
    fr = fetch(fav, opts, referer=target_url, allow_stdin_file=False)
    if fr.ok:
        h = find_head(root)
        h.append(elem("link", [("rel", "icon"), ("href", make_data_url(fr.data, fr.mime))], inserted_close=True))


def unwrap_noscript_nodes(root: Node) -> None:
    for n in list(walk(root)):
        if n.kind == "element" and n.name == "noscript" and n.parent is not None:
            par = n.parent
            idx = par.children.index(n)
            par.children.pop(idx)
            repl = [comment("noscript")] + n.children + [comment("/noscript")]
            for r in repl:
                r.parent = par
            par.children[idx:idx] = repl


def parent_name(n: Node) -> str:
    return n.parent.name if n.parent and n.parent.kind == "element" else ""


def process_document(root: Node, opts: Options, source_url: Optional[str], target_url: Optional[str],
                     add_head_extras: bool = True, frame_mode: bool = False) -> str:
    ensure_structure(root)
    existing_base = first_base_href(root)
    if opts.base_url:
        insert_or_update_base(root, opts.base_url)
        base = opts.base_url
    else:
        base = existing_base or source_url

    if opts.unwrap_noscript:
        unwrap_noscript_nodes(root)

    # First pass: remove refresh http-equiv and process all assets/URLs.
    for n in list(walk(root)):
        if n.kind != "element":
            continue
        name = n.name
        referer = source_url
        if name == "meta":
            hv = get_attr(n, "http-equiv")
            if hv is not None and hv.lower() == "refresh":
                del_attr(n, "http-equiv")

        if name == "style":
            if opts.no_css:
                n.children = []
            else:
                css = "".join(c.data if c.kind == "text" else serialize(c) for c in n.children)
                n.children = [text(process_css(css, base, opts, referer))]
                n.children[0].parent = n

        elif name == "script":
            if opts.no_js:
                del_attr(n, "src")
                n.children = []
            elif has_attr(n, "src"):
                src = get_attr(n, "src") or ""
                ok, content, _mime, resolved = fetch_text_asset(src, base, opts, referer)
                if ok:
                    del_attr(n, "src")
                    n.children = [text(content)] if content else []
                    for c in n.children: c.parent = n
                else:
                    set_attr(n, "src", content)  # content holds resolved URL

        elif name == "link":
            rels = rel_tokens(n)
            if "stylesheet" in rels:
                if opts.no_css:
                    del_attr(n, "href")
                elif has_attr(n, "href"):
                    href = get_attr(n, "href") or ""
                    ok, css_text, mime, resolved = fetch_text_asset(href, base, opts, referer)
                    if ok:
                        processed = process_css(css_text, resolved or base, opts, resolved or referer)
                        set_attr(n, "href", make_data_url(processed.encode("utf-8"), mime or "text/css"))
                    else:
                        set_attr(n, "href", css_text)
            elif "icon" in rels or "apple-touch-icon" in rels or "shortcut" in rels:
                if opts.no_images:
                    del_attr(n, "href")
                elif has_attr(n, "href"):
                    set_asset_attr(n, "href", get_attr(n, "href") or "", base, opts, referer, "image")
            elif "preload" in rels and "modulepreload" not in rels:
                # Observed behavior strips rel=preload when the resource is not embedded.
                del_attr(n, "rel")
            elif has_attr(n, "href") and ("canonical" in rels or "modulepreload" in rels):
                set_attr(n, "href", absolutize_or_data(get_attr(n, "href") or "", base))

        elif name in ("img",):
            if opts.no_images:
                if has_attr(n, "src"):
                    set_attr(n, "src", PLACEHOLDER_PNG)
                if has_attr(n, "srcset"):
                    set_attr(n, "srcset", process_srcset(get_attr(n, "srcset") or "", base, opts, referer, True))
            else:
                if has_attr(n, "src"):
                    set_asset_attr(n, "src", get_attr(n, "src") or "", base, opts, referer, "image")
                if has_attr(n, "srcset"):
                    set_attr(n, "srcset", process_srcset(get_attr(n, "srcset") or "", base, opts, referer, False))

        elif name == "input":
            typ = (get_attr(n, "type") or "").lower()
            if typ == "image" and has_attr(n, "src"):
                if opts.no_images:
                    set_attr(n, "src", PLACEHOLDER_PNG)
                else:
                    set_asset_attr(n, "src", get_attr(n, "src") or "", base, opts, referer, "image")

        elif name == "body":
            if has_attr(n, "background"):
                if opts.no_images:
                    del_attr(n, "background")
                else:
                    set_asset_attr(n, "background", get_attr(n, "background") or "", base, opts, referer, "image")

        elif name == "audio":
            if has_attr(n, "src"):
                if opts.no_audio:
                    del_attr(n, "src")
                else:
                    set_asset_attr(n, "src", get_attr(n, "src") or "", base, opts, referer, "audio")

        elif name == "video":
            if has_attr(n, "poster"):
                if opts.no_images:
                    set_attr(n, "poster", PLACEHOLDER_PNG)
                else:
                    set_asset_attr(n, "poster", get_attr(n, "poster") or "", base, opts, referer, "image")
            if has_attr(n, "src"):
                if opts.no_video:
                    del_attr(n, "src")
                else:
                    set_asset_attr(n, "src", get_attr(n, "src") or "", base, opts, referer, "video")

        elif name == "source":
            pn = parent_name(n)
            if has_attr(n, "srcset"):
                if opts.no_images or pn == "picture":
                    set_attr(n, "srcset", process_srcset(get_attr(n, "srcset") or "", base, opts, referer, opts.no_images))
            if has_attr(n, "src"):
                if (pn == "audio" and opts.no_audio) or (pn == "video" and opts.no_video):
                    del_attr(n, "src")
                elif pn in ("audio", "video"):
                    set_asset_attr(n, "src", get_attr(n, "src") or "", base, opts, referer, pn)

        elif name in ("iframe", "frame"):
            if has_attr(n, "src"):
                if opts.no_frames:
                    set_attr(n, "src", "")
                else:
                    src = get_attr(n, "src") or ""
                    resolved = resolve_url(src, base)
                    if resolved is None:
                        set_attr(n, "src", make_data_url(b"<html><head></head><body></body></html>", "text/plain"))
                    else:
                        fr = fetch(resolved, opts, referer=referer, allow_stdin_file=(not opts.stdin_target))
                        if fr.ok:
                            try:
                                html_s = decode_bytes(fr.data, fr.mime)
                            except Exception:
                                html_s = fr.data.decode("utf-8", "replace")
                            subroot = parse_html(html_s)
                            # Process nested assets, but do not add robots/CSP/metadata.
                            subhtml = process_document(subroot, opts, resolved, resolved, add_head_extras=False, frame_mode=True)
                            subhtml = subhtml[:-1] if subhtml.endswith("\n") else subhtml
                            set_attr(n, "src", make_data_url(subhtml.encode("utf-8"), fr.mime or "text/html"))
                        elif fr.kind in ("blocked", "network", "http_error"):
                            set_attr(n, "src", resolved)
                        else:
                            del_attr(n, "src")

        elif name == "a" and has_attr(n, "href"):
            set_attr(n, "href", absolutize_or_data(get_attr(n, "href") or "", base))
        elif name == "area" and has_attr(n, "href"):
            set_attr(n, "href", absolutize_or_data(get_attr(n, "href") or "", base))
        elif name == "form" and has_attr(n, "action"):
            set_attr(n, "action", absolutize_or_data(get_attr(n, "action") or "", base))

    if add_head_extras:
        # Favicon is inserted before robots metadata in the observed output.
        insert_favicon_if_any(root, target_url, opts)
        ensure_csp(root, opts)
        ensure_robots(root)
        ensure_encoding_meta(root, opts.encoding)

    return serialize_document(root, final_newline=True)


# --- Output and main -------------------------------------------------------

def extract_title(root: Node) -> str:
    t = first_element(root, "title")
    if not t:
        return ""
    def gather(n: Node) -> str:
        if n.kind == "text": return n.data
        return "".join(gather(c) for c in n.children)
    return gather(t)


def sanitize_title(title: str) -> str:
    # Observed substitutions: / -> _, : -> " - ", ? and quotes removed,
    # < > become brackets, | becomes '-'.  Keep most other characters.
    out = []
    for ch in title:
        if ch == "/" or ch == "\\": out.append("_")
        elif ch == ":": out.append(" - ")
        elif ch in ('"', "?", "\0", "\n", "\r", "\t"):
            pass
        elif ch == "<": out.append("[")
        elif ch == ">": out.append("]")
        elif ch == "|": out.append("-")
        else: out.append(ch)
    return "".join(out).strip()


def timestamp(now: Optional[_dt.datetime] = None, filename: bool = False) -> str:
    now = now or _dt.datetime.now(_dt.timezone.utc)
    s = now.strftime("%Y-%m-%dT%H:%M:%SZ")
    return s.replace(":", "_") if filename else s


def apply_output_template(path: str, title: str, ts_file: str) -> str:
    if path == "-":
        return path
    return path.replace("%title%", sanitize_title(title)).replace("%timestamp%", ts_file)


def metadata_comment(target_url: Optional[str]) -> str:
    ts = timestamp()
    if target_url and urllib.parse.urlparse(target_url).scheme == "file":
        return f"<!-- Saved from local source at {ts} using monolith v{VERSION} -->\n"
    if target_url:
        return f"<!-- Saved from {target_url} at {ts} using monolith v{VERSION} -->\n"
    return ""


def wrap_mhtml(html_s: str) -> bytes:
    s = (
        "MIME-Version: 1.0\r\n"
        f"Content-Type: multipart/related; boundary=\"{BOUNDARY}\"\r\n"
        "\r\n"
        f"--{BOUNDARY}\r\n"
        "Content-Type: text/html; charset=\"utf-8\"\r\n"
        "Content-Location: http://example.com/\r\n"
        "\r\n"
        + html_s +
        f"\r\n--{BOUNDARY}--\r\n"
    )
    return s.encode("utf-8", "replace")


def write_output(data: bytes, opts: Options, title: str) -> None:
    out = opts.output
    if out is None or out == "-":
        sys.stdout.buffer.write(data)
        return
    out_path = apply_output_template(out, title, timestamp(filename=True))
    # Let Python raise normally for missing parents; the reference panics, but a
    # regular failure is sufficient for use and tests generally avoid this case.
    with open(out_path, "wb") as f:
        f.write(data)


def main(argv: List[str]) -> int:
    try:
        opts = parse_args(argv)
    except SystemExit as e:
        return int(e.code)

    if opts.help:
        print_help(); return 0
    if opts.version:
        sys.stdout.write(f"monolith {VERSION}\n"); return 0

    if opts.encoding:
        try:
            codecs.lookup(opts.encoding)
        except LookupError:
            sys.stderr.write(f'Error: unknown encoding "{opts.encoding}"\n')
            return 1

    cookie_err = load_cookies(opts)
    if cookie_err:
        sys.stderr.write(cookie_err + "\n")
        return 1

    assert opts.target is not None
    opts.stdin_target = (opts.target == "-")
    target_url, err = normalize_target(opts.target)
    if err:
        if not opts.quiet:
            sys.stderr.write(err + "\n")
        return 1

    content_type = ""
    data: bytes
    if opts.stdin_target:
        data = sys.stdin.buffer.read()
        source_url = None
    elif target_url and urllib.parse.urlparse(target_url).scheme == "file":
        fr = fetch(target_url, opts, is_target=True, allow_stdin_file=True)
        if not fr.ok:
            if not opts.quiet:
                sys.stderr.write("Error: could not retrieve target document\n")
            return 1
        data, content_type, source_url = fr.data, fr.mime, target_url
    else:
        # Domain filters apply to the target document; blocked targets produce
        # only the final high-level error.
        if target_url and not allowed_by_domains(target_url, opts):
            if not opts.quiet:
                sys.stderr.write("Error: could not retrieve target document\n")
            return 1
        fr = fetch(target_url or "", opts, is_target=True, allow_stdin_file=False)
        if not fr.ok:
            if not opts.quiet:
                sys.stderr.write("Error: could not retrieve target document\n")
            return 1
        data, content_type, source_url = fr.data, fr.mime, target_url

    try:
        html_s = decode_bytes(data, content_type, opts.encoding)
    except LookupError:
        sys.stderr.write(f'Error: unknown encoding "{opts.encoding}"\n')
        return 1

    root = parse_html(html_s)
    title_for_output = extract_title(root)
    html_out = process_document(root, opts, source_url, target_url, add_head_extras=True)
    if not opts.no_metadata and not opts.stdin_target:
        html_out = metadata_comment(target_url) + html_out

    out_bytes = wrap_mhtml(html_out) if opts.mhtml else html_out.encode("utf-8", "replace")
    try:
        write_output(out_bytes, opts, title_for_output)
    except Exception as e:
        # Approximate the reference panic enough to make failures visible.
        sys.stderr.write(f"could not prepare output: {e}\n")
        return 101
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
